#!/bin/bash
source /private/tmp/claude-501/-Users-kyle-Developer-grantiva-cli/b9f2e919-f7a5-4b94-a1bc-202f523560f4/scratchpad/cov3-android/env.sh
cd $P
for i in 1 2 3; do rec FIX1-home "uptime; adb -s emulator-5554 shell am force-stop com.kylebrowning.landmarks; \$GRANTIVA diff capture --device emulator-5554 --no-build > $E/FIX1-home/cap$i.out 2>&1; echo exit=\$?; grep -E 'Home|Launch' $E/FIX1-home/cap$i.out | head -3; cp .grantiva/captures/android/Home.png $E/FIX1-home/home$i.png; sips -Z 400 $E/FIX1-home/home$i.png --out $E/FIX1-home/home$i-small.png >/dev/null"; done
for i in 1 2 3; do rec FIX1-detach "uptime; t0=\$(python3 -I -c 'import time;print(time.time())'); \$GRANTIVA runner start --detach >/dev/null 2>&1; t1=\$(python3 -I -c 'import time;print(time.time())'); n=0; until \$GRANTIVA runner dump-hierarchy --format tree >/dev/null 2>&1; do n=\$((n+1)); sleep 0.5; [ \$n -gt 120 ] && break; done; t2=\$(python3 -I -c 'import time;print(time.time())'); python3 -I -c \"print('detach returned after %.1fs; first successful dump %.1fs after return (%d failed tries)'%(\$t1-\$t0,\$t2-\$t1,\$n))\"; \$GRANTIVA runner stop"; done
rec FIX1-teardown "uptime; adb -s emulator-5554 uninstall com.kylebrowning.landmarks; \$GRANTIVA build install --no-build --app-file $S/app-free-debug.apk --device emulator-5554 --no-launch; adb -s emulator-5554 shell pm list packages com.kylebrowning.landmarks; sleep 5; \$GRANTIVA emulator teardown --serial emulator-5554; sleep 3; \$GRANTIVA emulator ensure --name cov3-android; adb -s emulator-5554 shell pm list packages com.kylebrowning.landmarks; echo pm-exit=\$?"
rec FIX1-teardown "adb -s emulator-5554 install -r $S/app-free-debug.apk >/dev/null; adb -s emulator-5554 shell pm list packages com.kylebrowning.landmarks"
echo FIX1B-DONE
